<?php
require_once __DIR__.'/config.php';
$conn = db();
$event = active_event($conn);
$recent = [];
if ($event) {
    $query = $conn->prepare('SELECT a.scan_in,a.scan_out,a.attendance_status,s.first_name,s.last_name,s.middle_name,s.course,s.year_level,s.section FROM event_attendance a JOIN students s ON s.id=a.student_id WHERE a.event_id=? ORDER BY a.attendance_id DESC LIMIT 10');
    $query->bind_param('i', $event['id']);
    $query->execute();
    $recent = $query->get_result();
}
